INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34711, 'Romans 14:22', 'Romans', 14, 22, 'په کوم شي چې ته عقیده لرې، هغه د خدای او په خپل منځ کې وساته. بختور دي هغه خلک چې خپل ځانونه د هغه څه په خاطر چې د هغوی په نظر کې سم دي او تر‌سره کوي یې، مجرم نه ګڼي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_22.mp3', '', 1761754199, 1761754199),
(34712, 'Romans 14:23', 'Romans', 14, 23, 'خو که چېرې څوک کوم څه وخوري او په هغه باندې شکمن وي، نو هغه محکوم دی، ځکه چې هغه د ایمان له مخې دا عمل نه کوي او هر عمل چې د ایمان له مخې نه وي، هغه ګناه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_23.mp3', '', 1761754199, 1761754199),
(34713, 'John 12:1', 'John', 12, 1, 'د فسحې د اختر نه شپږ ورځې مخکې عیسی بیت‌عنیا ته چې ایلعازر په کې اوسېده، یعنې هماغه سړی چې هغه د مرګ نه وروسته بېرته راژوندی کړی ؤ، راغی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_1.mp3', '', 1761754199, 1761754199),
(34714, 'John 12:2', 'John', 12, 2, 'هغوی هلته د عیسی دپاره د ماښام ډوډۍ تیاره کړې وه. مرتا د هغوی خدمت کاوه او ایلعازر هم د عیسی سره ډوډۍ ته ناست ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_2.mp3', '', 1761754199, 1761754199),
(34715, 'John 12:3', 'John', 12, 3, 'په دې وخت کې مریم یو بوتل قیمتي عطر چې نیم لیتر ؤ او د یو ډول خالصه خوشبویه ملهمو څخه جوړ شوي وو، راواخیستل او د عیسی په پښو باندې یې واچول او د هغه پښې یې په خپلو ویښتانو باندې وچې کړلې او ټول کور د عطرو د خوشبویۍ نه ډک شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_3.mp3', '', 1761754199, 1761754199),
(34716, 'John 12:4', 'John', 12, 4, 'خو یهودا اسخریوتي چې د عیسی د شاګردانو څخه ؤ او وروسته یې د هغه سره خیانت وکړ، وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_4.mp3', '', 1761754199, 1761754199),
(34717, 'John 12:5', 'John', 12, 5, '«دا عطر ولې د درېو سوو سپینو زرو په سکو باندې خرڅ نه شول چې پیسې یې غریبانو ته ورکړل شوې وای؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_5.mp3', '', 1761754199, 1761754199),
(34718, 'John 12:6', 'John', 12, 6, 'هغه دا خبره د دې دپاره ونه کړه چې ګنې د هغه سره د غریبانو غم ؤ، بلکې په دې خاطر چې هغه خپله غل ؤ او څرنګه چې هغه د پیسو د ساتلو مسوولیت په غاړه درلود، نو اکثره وخت به یې یو څه پیسې د خپل ځان دپاره پټولې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_6.mp3', '', 1761754199, 1761754199),
(34719, 'John 12:7', 'John', 12, 7, 'عیسی وویل: «د هغې سره کار مه لرئ، هغې زه د ښخولو دپاره تیار کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_7.mp3', '', 1761754199, 1761754199),
(34720, 'John 12:8', 'John', 12, 8, 'ځکه چې غریبان به تل ستاسو سره وي، خو زه به تل تاسو سره نه یم.» د ایلعازر په ضد دسیسه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_8.mp3', '', 1761754199, 1761754199),
(34721, 'John 12:9', 'John', 12, 9, 'زیات شمېر خلک خبر شول چې عیسی په بیت‌عنیا کې دی، نو هغوی هلته ورغلل. یوازې د دې دپاره نه چې عیسی وویني بلکې ایلعازر چې عیسی راژوندی کړی ؤ، هم وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_9.mp3', '', 1761754199, 1761754199),
(34722, 'John 12:10', 'John', 12, 10, 'نو مشرانو کاهنانو پرېکړه وکړه چې ایلعازر هم ووژني،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_10.mp3', '', 1761754199, 1761754199),
(34723, 'John 12:11', 'John', 12, 11, 'ځکه چې د هغه له امله ډېرو خلکو هغوی پرېښودل او په عیسی باندې یې ایمان راوړ. په بریالیتوب سره اورشلیم ته د عیسی ننوتل (متي ۲۱‏:‌۱‌‏-‌۱۱ او مرقوس ۱۱‏:‌۱‌‏-‌۱۱ او لوقا ۱۹‏:‌۲۸‌‏-‌۴۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_11.mp3', '', 1761754199, 1761754199),
(34724, 'John 12:12', 'John', 12, 12, 'په بله ورځ ګڼ شمېر خلک چې د اختر دپاره راغلي وو، خبر شول چې عیسی اورشلیم ته راروان دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_12.mp3', '', 1761754199, 1761754199),
(34725, 'John 12:13', 'John', 12, 13, 'نو هغوی د خرما د ونو څانګې واخیستلې او د هغه مخې ته ورووتل او چیغې یې وهلې: «ژوندی دې وي! مبارک دی وي هغه څوک چې د څښتن په نوم راځي! مبارک دي وي د اسراییلو پاچا!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_13.mp3', '', 1761754199, 1761754199),
(34726, 'John 12:14', 'John', 12, 14, 'عیسی یو کوټی پیدا کړ او په هغه باندې سپور شو، لکه څنګه چې د خدای په کلام کې لیکل شوي دي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_14.mp3', '', 1761754199, 1761754199),
(34727, 'John 12:15', 'John', 12, 15, '«ای د صهیون خلکو، نور مه وېرېږئ! ګوره، ستا پاچا دی راروان هغه سپور دی په کوټي باندې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_15.mp3', '', 1761754199, 1761754199),
(34728, 'John 12:16', 'John', 12, 16, 'په پیل کې شاګردان د دې شیانو په معنی باندې پوه نه شول، خو کله چې عیسی خپل جلال ته ورسېده، نو هغوی ته ور په یاد شول چې دا شیان د هغه په هکله لیکل شوي وو او د هغه سره همداسې وشول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_16.mp3', '', 1761754199, 1761754199),
(34729, 'John 12:17', 'John', 12, 17, 'کله چې عیسی ایلعازر ته غږ وکړ او هغه یې راژوندی کړ او د قبر څخه یې راوویست، نو زیات شمېر خلک هلته موجود وو. هغوی چې څه لیدلي او اورېدلي وو د هغې په هکله یې نورو خلکو ته شاهدي ورکوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_17.mp3', '', 1761754199, 1761754199),
(34730, 'John 12:18', 'John', 12, 18, 'نو ګڼ شمېر خلک د هغه هرکلي ته ورغلل، ځکه چې هغوی اورېدلي وو چې عیسی دا معجزه ښودلې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_18.mp3', '', 1761754199, 1761754199),
(34731, 'John 12:19', 'John', 12, 19, 'نو بیا فریسیانو یو بل ته سره وویل: «تاسو ګورئ چې مونږ هېڅ نه شو کولای، ټوله نړۍ هغه پسې روانه ده.» ځینې یونانیان غواړي چې د عیسی سره خبرې وکړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_19.mp3', '', 1761754199, 1761754199),
(34732, 'John 12:20', 'John', 12, 20, 'په اختر کې چې د عبادت دپاره اورشلیم ته کوم خلک راغلي وو په هغوی کې ځینې یونانیان هم وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_20.mp3', '', 1761754199, 1761754199),
(34733, 'John 12:21', 'John', 12, 21, 'هغوی فیلیپوس ته چې د جلیل د بیت‌صیدا ؤ، راغلل او ورته ویې ویل: «ای ښاغلیه، مونږ غواړو چې عیسی ووینو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_21.mp3', '', 1761754199, 1761754199),
(34734, 'John 12:22', 'John', 12, 22, 'فیلیپوس لاړ او اندریاس ته یې وویل او هغوی دواړه لاړل چې عیسی خبر کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_22.mp3', '', 1761754199, 1761754199),
(34735, 'John 12:23', 'John', 12, 23, 'عیسی هغوی ته وویل: «اوس هغه وخت رارسېدلی دی چې د انسان زوی جلال ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_23.mp3', '', 1761754199, 1761754199),
(34736, 'John 12:24', 'John', 12, 24, 'په یقین سره زه تاسو ته دا وایم چې که د غنمو یوه دانه په خاوره کې ونه لویږي او له منځه لاړه نه شي، نو هغه به هماغه یوه دانه پاتې شي. خو که چېرې هغه له منځه لاړه شي نو ډېرې غلې دانې به راوړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_24.mp3', '', 1761754199, 1761754199),
(34737, 'John 12:25', 'John', 12, 25, 'په چا باندې چې په دې نړۍ کې خپل ځان ګران وي نو هغه به له لاسه ورکړي. خو که څوک په نړۍ کې د خپل ځان نه تېر شي، نو هغه به تل ترتله خپل ژوند وساتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_25.mp3', '', 1761754199, 1761754199),
(34738, 'John 12:26', 'John', 12, 26, 'که څوک غواړي چې زما خدمت وکړي، نو هغه دې ما پسې راځي او چېرته چې زه یم نو زما خدمتګار به هم هلته وي. څوک چې زما خدمت کوي نو زما پلار به هغه سرلوړی کړي. عیسی د خپل مرګ په هکله خبرې کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_26.mp3', '', 1761754199, 1761754199),
(34739, 'John 12:27', 'John', 12, 27, 'اوس زما زړه نا‌ارامه دی. څه ووایم؟ ایا ووایم: ‹ای پلاره، ما د دې ساعت د کړاو او ځورېدنې نه وساته؟› خو زه دې نړۍ ته د دې دپاره راغلی یم چې وکړېږم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_27.mp3', '', 1761754199, 1761754199),
(34740, 'John 12:28', 'John', 12, 28, 'ای پلاره، خپل نوم ته جلال ورکړه!» هغه وخت د اسمان نه یو اواز راغی او ویې ویل: «ما جلال ورکړی دی او بیا به هم جلال ورکړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_28.mp3', '', 1761754199, 1761754199),
(34741, 'John 12:29', 'John', 12, 29, 'کوم خلک چې په هغه ځای کې ولاړ وو او دا اواز یې واورېد، نو ځینو یې وویل: «دا د تندر اواز ؤ.» خو نورو وویل: «فرښتې د هغه سره خبرې وکړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_29.mp3', '', 1761754199, 1761754199),
(34742, 'John 12:30', 'John', 12, 30, 'خو عیسی هغوی ته وویل: «دا اواز زما په خاطر نه بلکې ستاسو په خاطر ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_30.mp3', '', 1761754199, 1761754199),
(34743, 'John 12:31', 'John', 12, 31, 'اوس د دې وخت رارسېدلی چې خدای به د نړۍ د خلکو په هکله قضاوت کوي او د دې نړۍ واکمن یعنې شیطان به شړل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_31.mp3', '', 1761754199, 1761754199),
(34744, 'John 12:32', 'John', 12, 32, 'کله چې زه د ځمکې نه پورته وخېژول شم، نو ټول انسانان به خپل ځان ته راکاږم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_32.mp3', '', 1761754199, 1761754199),
(34745, 'John 12:33', 'John', 12, 33, 'د عیسی د خبرې اشاره دې ته وه چې هغه به په څه قسم مرګ مړ کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_33.mp3', '', 1761754199, 1761754199),
(34746, 'John 12:34', 'John', 12, 34, 'خلکو عیسی ته وویل: «زمونږ شریعت وایي چې مسیح به تل ترتله ژوندی وي. نو بیا ته څنګه ویلی شې چې د انسان زوی باید پورته وخېژول شي؟ دا د انسان زوی څوک دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_34.mp3', '', 1761754199, 1761754199),
(34747, 'John 12:35', 'John', 12, 35, 'عیسی هغوی ته وویل: «ستاسو سره د لږ نور وخت دپاره رڼا شته. ترڅو پورې چې دا رڼا ستاسو سره ده نو تاسو ګرځئ، هسې نه چې تیاره درباندې راشي. ځکه څوک چې په تیاره کې ګرځي هغه نه پوهیږي چې چېرته روان دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_35.mp3', '', 1761754199, 1761754199),
(34748, 'John 12:36', 'John', 12, 36, 'تر هغې پورې چې رڼا درسره ده، نو په رڼا باندې ایمان راوړئ د دې دپاره چې تاسو د رڼا بچیان شئ.» کله چې عیسی خپلې خبرې پای ته ورسولې، نو لاړ او د هغوی نه پټ شو. ډېرو خلکو په عیسی باندې ایمان رانه وړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_36.mp3', '', 1761754199, 1761754199),
(34749, 'John 12:37', 'John', 12, 37, 'سره له دې چې عیسی د هغوی په مخکې ډېرې معجزې وښودلې خو هغوی په هغه باندې ایمان رانه وړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_37.mp3', '', 1761754199, 1761754199),
(34750, 'John 12:38', 'John', 12, 38, 'ترڅو د اشعیا پیغمبر هغه خبرې رښتیا شي چې ویلي یې وو: «ای څښتنه، چا زمونږ په پیغام باندې باور کړی دی؟ چاته څښتن خپل قدرت ښودلی دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_38.mp3', '', 1761754199, 1761754199),
(34751, 'John 12:39', 'John', 12, 39, 'نو هغوی ونه شو کولای چې ایمان راوړي. اشعیا پیغمبر دا هم ویلي دي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_39.mp3', '', 1761754199, 1761754199),
(34752, 'John 12:40', 'John', 12, 40, '«خدای د هغوی سترګې ړندې کړې دي، او د هغوی زړونه یې سخت کړي دي، چې په سترګو باندې څه ونه ویني او په زړونو کې ورباندې پوه نه شي او ماته را ونه ګرځي چې زه یې روغ کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_40.mp3', '', 1761754199, 1761754199),
(34753, 'John 12:41', 'John', 12, 41, 'اشعیا دا د دې دپاره وویل چې د عیسی جلال یې لیدلی ؤ او د هغه په هکله یې خبرې وکړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_41.mp3', '', 1761754199, 1761754199),
(34754, 'John 12:42', 'John', 12, 42, 'سره له دې بیاهم ډېرو یهودي مشرانو په هغه باندې ایمان راوړ، خو د فریسیانو له وېرې یې د خپل ایمان راوړلو اقرار نه کاوه، هسې نه چې د کنیسې څخه یې وشړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_42.mp3', '', 1761754199, 1761754199),
(34755, 'John 12:43', 'John', 12, 43, 'ځکه چې هغوی د خدای له خوا د ستاینې په ځای د انسان ستاینه زیاته خوښوله. د عیسی د کلام په وسیله قضاوت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_43.mp3', '', 1761754199, 1761754199),
(34756, 'John 12:44', 'John', 12, 44, 'نو عیسی په لوړ اواز وویل: «هرڅوک چې په ما باندې ایمان راوړي، نو هغه نه یوازې دا چې په ما باندې یې ایمان راوړی بلکې په هغه چا باندې یې هم راوړی دی چې زه یم رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john12_verse_44.mp3', '', 1761754199, 1761754199),
