(34801, 'Mark 15:39', 'Mark', 15, 39, 'کله چې هغه رومي منصبدار چې عیسی ته مخامخ ولاړ ؤ ولیدل چې هغه څنګه ساه ورکړه، نو ویې ویل: «دا سړی په رښتیا د خدای زوی ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_39.mp3', '', 1761754199, 1761754199),
(34802, 'Mark 15:40', 'Mark', 15, 40, 'په هغه ځای کې یو څو ښځې هم وې چې د لېرې نه یې کتل. په هغوی کې مریم چې د مجدلیې د ښار څخه وه او مریم د کشر یعقوب، یوشا او سالومې مور وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_40.mp3', '', 1761754199, 1761754199),
(34803, 'Mark 15:41', 'Mark', 15, 41, 'کوم وخت چې عیسی په جلیل کې ؤ، نو دا ښځې ورسره ملګرې وې او خدمت یې ورته کاوه. ډېرې نورې ښځې چې د هغه سره اورشلیم ته راغلې وې هم په هغه ځای کې وې. د عیسی ښخول (متي ۲۷‏:‌۵۷‌‏-‌۶۱ او لوقا ۲۳‏:‌۵۰‌‏-‌۵۶ او یوحنا ۱۹‏:‌۳۸‌‏-‌۴۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_41.mp3', '', 1761754199, 1761754199),
(34804, 'Mark 15:42', 'Mark', 15, 42, 'دا د جمعې ورځ وه یعنې د سبت څخه یوه ورځ مخکې د اختر دپاره د تیاري نیولو ورځ وه. څنګه چې ماښام شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_42.mp3', '', 1761754199, 1761754199),
(34805, 'Mark 15:43', 'Mark', 15, 43, 'یوسف چې د رامه د ښار څخه ؤ او د شورا یو عزتمن غړی ؤ او د خدای د پاچاهۍ د راتللو انتظار یې کاوه، په زړورتیا سره پیلاتوس ته ورغی او د عیسی مړی یې ترې وغوښت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_43.mp3', '', 1761754199, 1761754199),
(34806, 'Mark 15:44', 'Mark', 15, 44, 'کله چې پیلاتوس خبر شو چې عیسی مړ شوی دی، نو هغه حیران شو. هغه عسکري منصبدار یې راوغوښت او پوښتنه یې ترې وکړه: «ایا هغه مړ شوی دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_44.mp3', '', 1761754199, 1761754199),
(34807, 'Mark 15:45', 'Mark', 15, 45, 'کله چې پیلاتوس د هغه منصبدار له خوا خبر شو چې عیسی وخته مړ شوی دی، نو یوسف ته یې اجازه ورکړه چې مړی یوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_45.mp3', '', 1761754199, 1761754199),
(34808, 'Mark 15:46', 'Mark', 15, 46, 'نو یوسف د کتان کفن راواخیست، د عیسی مړی یې د صلیب څخه راښکته کړ، په هغه کې یې تاو کړ او په یو قبر کې چې په یو ګټ کې کیندل شوی ؤ کېښود. بیا یې یوه غټه تیږه د غار خولې ته راورغړوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_46.mp3', '', 1761754199, 1761754199),
(34809, 'Mark 15:47', 'Mark', 15, 47, 'مریم مجدلیې او د یوشا مور مریم ولیدل چې د عیسی مړی یې په کوم ځای کې ایښی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark15_verse_47.mp3', '', 1761754199, 1761754199),
(34810, 'Revelation 16:1', 'Revelation', 16, 1, 'بیا ما د خدای د کور نه یو لوړ اواز واورېد چې هغو اوو فرښتو ته یې ویل: «لاړې شئ او د خدای د قهر او غضب اووه جامونه په ځمکه باندې توی کړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_1.mp3', '', 1761754199, 1761754199);